UPDATE equations x SET description = 'Plan 3: Rissklasse aus den Tab.-18-Kriterien — R0-B "keine Rissbreitenveränderung bzw. Neurissbildung" (L3677) ⇒ 0; R1-B bis max. 0,2 mm (L3680) ⇒ 1; R2-B bis max. 0,5 mm (L3684) ⇒ 2; R3-B bis max. 1,0 mm, Rissversatz bis 0,5 mm (L3688) ⇒ 3; außerhalb der gedruckten Klassen ⇒ 9 (fll_gar-J-2); alle drei Eingaben sind erforderlich (0 eintragen, wenn keine); die manuelle rissklasse bleibt Produzent (fll_gar-D-3).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-05' AND x.equation_number = 'FLL-GAR-05-D2';
