UPDATE fields x SET description = 'Plan 3: Zeilen je Pflanzenart (L1313 "Im Einzelfall ist der Nachweis auf Wurzel- und Rhizomfestigkeit zu führen. Bei vorgesehener Bepflanzung …"); aggressive Arten → pflanzen_aggressiv_count (FLL-GAR-24-D2); REQ-11 (leere Bedingung) STAGED (fll_gar-G-13); die Tab.-29-Liste als Vorschlagsliste folgt, sobald gelesen (fll_gar-U-3); bep_pflanzenarten (Freitext) bleibt. — Coverage block 5b (2026-09-30): Tab.-29 column added (TAB29, block 1).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-24' AND x.symbol = 'pflanzenarten';
