UPDATE fields x SET description = 'Plan 3: Ausgabe der Gleichung FLL-GAR-24-D2 (count_rows über pflanzenarten mit aggressiv == true); Grundlage für REQ-11 ("If required and abdichtung not inherently resistant: separate Wurzelschutzbahn") — Gate STAGED (fll_gar-G-13).' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-24' AND x.symbol = 'pflanzen_aggressiv_count';
UPDATE equations x SET description = 'Plan 3: Anzahl der Durchdringungs-/Einbauten-Zeilen — ersetzt den manuellen Zähler bep_durchdringungen_anzahl nach Ratifizierung (fll_gar-D-6); Text-Ableitung ohne gedruckte Formel (L1479 "Durchdringungen und technische Einbauten").' FROM worksheet_templates w JOIN standards s ON s.id = w.standard_id WHERE x.worksheet_template_id = w.id AND s.code = 'FLL-GAR-2023' AND w.code = 'FLL-GAR-24' AND x.equation_number = 'FLL-GAR-24-D1';
